class Solution:
    def scoreOfStudents(self, s: str, answers: List[int]) -> int:

        @cache
        def fn(lo, hi): 
            """Return possible answers of s[lo:hi]."""
            if lo+1 == hi: return {int(s[lo])}
            ans = set()
            for mid in range(lo+1, hi, 2): 
                for x in fn(lo, mid): 
                    for y in fn(mid+1, hi): 
                        if s[mid] == "+" and x + y <= 1000: ans.add(x + y)
                        elif s[mid] == "*" and x * y <= 1000: ans.add(x * y)
            return ans 

        target = eval(s)
        cand = fn(0, len(s))
        ans = 0 
        for x in answers: 
            if x == target: ans += 5
            elif x in cand: ans += 2
        return ans

from functools import lru_cache
class Solution:
    def possiblyEquals(self, s1: str, s2: str) -> bool:

        def getValidPrefixLength(s,start):
            end = start
            while end < len(s) and s[end].isdigit(): end += 1
            return end

        @lru_cache(None)
        def possibleLengths(s):
            """Return all possible lengths represented by numeric string s."""
            ans = {int(s)}
            for i in range(1, len(s)):
                # add all lengths by splitting numeric string s at i
                ans |= {x+y for x in possibleLengths(s[:i]) for y in possibleLengths(s[i:])}
            return ans

        @lru_cache(None)
        def dp(i, j, diff):
            """Return True if s1[i:] matches s2[j:] with given differences."""

            # If both have reached end return true if none of them are leading
            if i == len(s1) and j == len(s2): return diff == 0

            # s1 has not reached end and s1 starts with a digit
            if i < len(s1) and s1[i].isdigit():
                i2 = getValidPrefixLength(s1,i)
                for L in possibleLengths(s1[i:i2]):
                    # substract since lead of s2 decreases by L
                    if dp(i2, j, diff-L): return True

            # s2 has not reached end and s2 starts with a digit
            elif j < len(s2) and s2[j].isdigit():
                j2 = getValidPrefixLength(s2,j)
                for L in possibleLengths(s2[j:j2]):
                    # add since lead of s2 increase by L
                    if dp(i, j2, diff+L): return True

            # if none of them have integer prefix or a lead over the other
            elif diff == 0:
                # if only one of them has reached end or current alphabets are not the same
                if i == len(s1) or j == len(s2) or s1[i] != s2[j]: return False
                # skip same alphabets
                return dp(i+1, j+1, 0)

            # if none of them have integer prefix & s2 lead over s1
            elif diff > 0:
                # no s1 to balance s2's lead
                if i == len(s1): return False
                # move s1 pointer forward and reduce diff
                return dp(i+1, j, diff-1)

            # if none of them have integer prefix & s1 lead over s2
            else:
                # no s2 to balance s1's lead
                if j == len(s2): return False
                # move s2 pointer forward and increase diff
                return dp(i, j+1, diff+1)

        # start with starts of both s1 and s2 with no lead by any of them
        return dp(0, 0, 0)

class Solution:
    def countPyramids(self, grid):      
        # dp[i][j] represents the number of layers of the largest pyramid with (i, j) as the vertex.
        # Note that the 1-level pyramid is invalid in the problem, so it should be removed when summing.
        # Note that if grid[i][j] is 0, dp[i][j] will always be 0.
        # The dp recurrence formula is dp[i][j] = min(dp[i + 1][j - 1], dp[i + 1][j + 1]) + 1
        m, n, dp, cnt = len(grid), len(grid[0]), copy.deepcopy(grid), 0
        # triangle
        for i in range(m - 2, -1, -1):
            for j in range(1, n - 1):
                if dp[i][j] > 0 and dp[i + 1][j] > 0:
                    dp[i][j] = min(dp[i + 1][j - 1], dp[i + 1][j + 1]) + 1
                    cnt += dp[i][j] - 1
        # inverted triangle
        dp = grid
        for i in range(1, m):
            for j in range(1, n - 1):
                if dp[i][j] > 0 and dp[i - 1][j] > 0:
                    dp[i][j] = min(dp[i - 1][j - 1], dp[i - 1][j + 1]) + 1
                    cnt += dp[i][j] - 1
        return cnt

class Solution:
    def numberOfWays(self, corridor):
        seat, res, plant = 0, 1, 0
        for i in corridor:
            if i=='S':
                seat += 1
            else:
                if seat == 2:
                    plant += 1
            if seat == 3:
                res = res*(plant+1) % (10**9 + 7)
                seat , plant = 1 , 0
        if seat != 2:
            return 0
        return res

class Solution:
    def minimumTime(self, s):
        def minSum(nums):
            dp = [0]*len(nums)
            dp[0] = nums[0]
            for i in range(1, len(nums)):
                dp[i] = min(nums[i], nums[i] + dp[i-1])
            return min(0, min(dp))

        n = len(s)
        s1 = [1 if i == "1" else -1 for i in s]
        score = minSum(s1)

        return n + score

